import{_ as e,o as t,c as a,ae as o}from"./chunks/framework.EHGTsUvI.js";const c=JSON.parse('{"title":"Liquid Silos","description":"","frontmatter":{"title":"Liquid Silos"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/liquidsilos.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/liquidsilos.md"}'),r={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/liquidsilos.md"};function l(s,i,n,d,u,h){return t(),a("div",null,[...i[0]||(i[0]=[o('<h1 id="liquid-silos" tabindex="-1">Liquid Silos <a class="header-anchor" href="#liquid-silos" aria-label="Permalink to &quot;Liquid Silos&quot;">​</a></h1><p>Liquid Silos are storage buildings used to store liquid products such as milk, allowing players to stockpile liquids for later use in production.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Liquid Silos are used to store liquid products without requiring them to remain inside a tanker or other transport vehicle.</p><p>They are particularly useful for storing milk for production chains such as <strong>Cheese</strong>, <strong>Cake Batter</strong>, and <strong>Chocolate Milk</strong>.</p><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="_1-place-the-liquid-silo" tabindex="-1">1. Place the Liquid Silo <a class="header-anchor" href="#_1-place-the-liquid-silo" aria-label="Permalink to &quot;1. Place the Liquid Silo&quot;">​</a></h3><p>Purchase and place the Liquid Silo on your farm.</p><h3 id="_2-load-liquid" tabindex="-1">2. Load Liquid <a class="header-anchor" href="#_2-load-liquid" aria-label="Permalink to &quot;2. Load Liquid&quot;">​</a></h3><p>Bring the required liquid to the silo using a suitable tanker or transport vehicle.</p><p>Unload the liquid into the silo.</p><h3 id="_3-store-liquid" tabindex="-1">3. Store Liquid <a class="header-anchor" href="#_3-store-liquid" aria-label="Permalink to &quot;3. Store Liquid&quot;">​</a></h3><p>The liquid will remain stored inside the silo until it is needed.</p><h3 id="_4-remove-liquid" tabindex="-1">4. Remove Liquid <a class="header-anchor" href="#_4-remove-liquid" aria-label="Permalink to &quot;4. Remove Liquid&quot;">​</a></h3><p>When required, use a suitable tanker to collect the stored liquid and transport it to a factory or other destination.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Purchase Price</td><td>4,000 Coins</td></tr><tr><td>Storage Capacity</td><td>300 Units</td></tr></tbody></table><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>No special license required.</li><li>A suitable liquid tanker is required to transport liquids to and from the silo.</li></ul><h2 id="useful-information-tips" tabindex="-1">Useful Information &amp; Tips <a class="header-anchor" href="#useful-information-tips" aria-label="Permalink to &quot;Useful Information &amp; Tips&quot;">​</a></h2><ul><li>Useful for storing large quantities of milk.</li><li>Helps keep tankers available for other tasks.</li><li>Useful when supplying factories with large amounts of liquid ingredients.</li><li>Particularly useful for <strong>Cheese</strong>, <strong>Cake Batter</strong>, and <strong>Chocolate Milk</strong> production.</li></ul>',21)])])}const p=e(r,[["render",l]]);export{c as __pageData,p as default};
